const express = require("express");
const app = express();
app.use(express.json());

let nextId = 3;
const todos = [
  { id: 1, title: "Học Node", done: false },
  { id: 2, title: "Viết API", done: false },
];

app.get("/todos", (req, res) => res.json(todos));

app.post("/todos", (req, res) => {
  const todo = { id: nextId++, title: req.body.title, done: false };
  todos.push(todo);
  res.status(201).json(todo);
});

app.delete("/todos/:id", (req, res) => {
  const i = todos.findIndex((t) => t.id === Number(req.params.id));
  if (i === -1) return res.status(404).json({ error: "not found" });
  todos.splice(i, 1);
  res.sendStatus(204);
});

(async () => {
  const r = await app.inject({ method: "POST", url: "/todos", body: { title: "Deploy" } });
  console.log(r.statusCode, r.body);
  console.log((await app.inject("/todos")).json().length);
})();

