const express = require("express");
const app = express();
app.use(express.json());

const todos = [{ id: 1, title: "A" }];

app.put("/todos/:id", (req, res) => {
  const t = todos.find((x) => x.id === Number(req.params.id));
  if (!t) return res.status(404).json({ error: "not found" });
  t.title = req.body.title;
  res.json(t);
});

(async () => {
  const a = await app.inject({ method: "PUT", url: "/todos/1", body: { title: "Mới" } });
  const b = await app.inject({ method: "PUT", url: "/todos/5", body: { title: "x" } });
  console.log(a.statusCode, a.body);
  console.log(b.statusCode);
})();
